create or replace function public.claim_job_run(p_job_name text,p_lease_minutes integer default 120)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;if p_job_name!~'^[a-z0-9_.-]{1,100}$' then raise exception 'invalid job name';end if;perform pg_advisory_xact_lock(hashtext(p_job_name));update public.job_runs set status='failed',finished_at=now(),error_message='lease expired before completion' where job_name=p_job_name and status='running' and started_at<now()-make_interval(mins=>greatest(5,least(p_lease_minutes,1440)));if exists(select 1 from public.job_runs where job_name=p_job_name and status='running')then raise exception 'job already running' using errcode='55000';end if;insert into public.job_runs(job_name)values(p_job_name)returning id into v_id;return v_id;end;$$;
create or replace function public.claim_due_deletion_requests(p_limit integer default 25)returns setof public.deletion_requests language plpgsql security definer set search_path=public as $$begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;return query with claimed as(select id from public.deletion_requests where status in('pending','failed') and scheduled_for<=now() order by scheduled_for for update skip locked limit greatest(1,least(p_limit,100)))update public.deletion_requests d set status='processing',error_message=null from claimed where d.id=claimed.id returning d.*;end;$$;
revoke all on function public.claim_job_run(text,integer) from public,anon,authenticated;grant execute on function public.claim_job_run(text,integer) to service_role;
